const $=s=>document.querySelector(s);const toast=t=>{const e=$('.toast');e.textContent=t;e.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>e.classList.remove('visible'),3000)};
$('.menu').addEventListener('click',()=>{const open=$('#nav').classList.toggle('open');$('.menu').setAttribute('aria-expanded',open);$('.menu').setAttribute('aria-label',open?'Fechar menu':'Abrir menu')});document.querySelectorAll('#nav a').forEach(a=>a.addEventListener('click',()=>{$('#nav').classList.remove('open');$('.menu').setAttribute('aria-expanded','false')}));
const views={overview:['Visão geral','Bom dia, João ☀ Vamos acompanhar sua operação?','Produtos que movimentam sua loja','Margem real, sem surpresas'],orders:['Seus pedidos','86 pedidos recebidos. 24 aguardando envio.','Produtos nos pedidos de hoje','Dados demonstrativos'],products:['Seus produtos','Edite o estoque diretamente nas células da tabela.','Catálogo de produtos','Clique no estoque para editar'],stock:['Controle de estoque','3 produtos precisam da sua atenção.','Produtos com estoque baixo','Atualize o saldo nas células'],margin:['Margem real','Enxergue o lucro depois de todos os custos.','Ranking de margem por produto','Itens com prejuízo em destaque']};
function setView(view){document.querySelectorAll('[data-view]').forEach(b=>{b.classList.toggle('active',b.dataset.view===view);b.setAttribute('aria-pressed',String(b.dataset.view===view))});const v=views[view];$('#dashboard-title').textContent=v[0];$('#dashboard-sub').textContent=v[1];$('#table-title').textContent=v[2];$('#table-note').textContent=v[3];const body=$('tbody');const rows=Array.from(body.rows);if(view==='margin')rows.sort((a,b)=>parseFloat(b.cells[4].textContent.replace('−','-').replace(',','.'))-parseFloat(a.cells[4].textContent.replace('−','-').replace(',','.')));else rows.sort((a,b)=>a.cells[0].textContent.localeCompare(b.cells[0].textContent));rows.forEach(row=>body.append(row));}
document.querySelectorAll('[data-view]').forEach(b=>b.addEventListener('click',()=>setView(b.dataset.view)));$('[data-show-stock]').addEventListener('click',()=>setView('stock'));$('#try-table').addEventListener('click',()=>{setView('products');setTimeout(()=>$('td input').focus({preventScroll:true}),500)});
let weekly=false;$('#period').addEventListener('click',()=>{weekly=!weekly;$('#period').textContent=weekly?'▦ Últimos 7 dias ⌄':'▦ Hoje, 24 de outubro ⌄';$('#sales-total').innerHTML=weekly?'R$ 86.423<span>,70</span>':'R$ 12.845<span>,90</span>';$('#orders-total').textContent=weekly?'574':'86';$('.channel-panel .panel-heading>span').textContent=weekly?'Receita da semana':'Receita de hoje';const vals=weekly?['R$ 36.450,00','R$ 21.890,50','R$ 15.246,40','R$ 8.127,00','R$ 4.709,80']:['R$ 5.482,00','R$ 3.210,50','R$ 2.456,40','R$ 1.087,00','R$ 610,00'];document.querySelectorAll('.channel b').forEach((b,i)=>b.textContent=vals[i]);});
document.querySelectorAll('td input').forEach(input=>{try{const stored=localStorage.getItem(input.getAttribute('aria-label'));if(stored!==null)input.value=stored}catch{}input.addEventListener('change',()=>{if(input.value===''||!Number.isInteger(Number(input.value))||Number(input.value)<0){input.value=0}try{localStorage.setItem(input.getAttribute('aria-label'),input.value)}catch{}toast('Estoque de demonstração atualizado neste navegador.');});});
const dialog=$('#plan-dialog');let plan='';document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>{plan=b.dataset.plan;$('#selected-plan').textContent='Você escolheu o plano '+plan+'. Registre seu interesse nesta demonstração.';$('#interest-form').hidden=false;$('#form-success').hidden=true;dialog.showModal()}));$('.close-dialog').addEventListener('click',()=>dialog.close());$('#done').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});$('#interest-form').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));try{localStorage.setItem('sincro-interest',JSON.stringify({...data,plan}))}catch{toast('Não foi possível salvar no navegador. Verifique as configurações de armazenamento.');return}$('#interest-form').hidden=true;$('#form-success').hidden=false;});

document.querySelectorAll('[data-view]').forEach(b=>b.setAttribute('aria-pressed',String(b.classList.contains('active'))));
